package com.example.riskplatform.security;
import com.example.riskplatform.entity.SysUser;import lombok.Getter;import org.springframework.security.core.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.UserDetails;import java.util.*;
@Getter public class LoginUser implements UserDetails{private final SysUser user;private final List<String>permissions;private final List<String>roles;private final String dataScope;public LoginUser(SysUser u,List<String>p,List<String>r,String d){user=u;permissions=p;roles=r;dataScope=d==null?"SELF":d;}public Collection<?extends GrantedAuthority>getAuthorities(){List<GrantedAuthority>a=new ArrayList<>();permissions.forEach(x->a.add(new SimpleGrantedAuthority(x)));roles.forEach(x->a.add(new SimpleGrantedAuthority("ROLE_"+x)));return a;}public String getPassword(){return user.getPasswordHash();}public String getUsername(){return user.getUsername();}public boolean isAccountNonExpired(){return true;}public boolean isAccountNonLocked(){return true;}public boolean isCredentialsNonExpired(){return true;}public boolean isEnabled(){return user.getStatus()!=null&&user.getStatus()==1;}}
